        public static IArmorGetter ArmorFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new ArmorBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IArmorGetter ArmorFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return ArmorFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.OBND:
                {
                    _ObjectBoundsLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Armor_FieldIndex.ObjectBounds;
                }
                case RecordTypeInts.FULL:
                {
                    _NameLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.Name;
                }
                case RecordTypeInts.SCRI:
                {
                    _ScriptLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.Script;
                }
                case RecordTypeInts.EITM:
                {
                    _ObjectEffectLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.ObjectEffect;
                }
                case RecordTypeInts.BMDT:
                {
                    _BipedDataLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)Armor_FieldIndex.BipedData;
                }
                case RecordTypeInts.MODL:
                case RecordTypeInts.MODT:
                case RecordTypeInts.MODS:
                case RecordTypeInts.MODB:
                case RecordTypeInts.MODD:
                {
                    if (!lastParsed.ParsedIndex.HasValue
                        || lastParsed.ParsedIndex.Value <= (int)Armor_FieldIndex.BipedData)
                    {
                        this.MaleBipedModel = ModelBinaryOverlay.ModelFactory(
                            stream: stream,
                            package: _package,
                            translationParams: translationParams.DoNotShortCircuit());
                        return new ParseResult((int)Armor_FieldIndex.MaleBipedModel, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Armor_FieldIndex.MaleBipedModel)
                    {
                        this.MaleWorldModel = ModelBinaryOverlay.ModelFactory(
                            stream: stream,
                            package: _package,
                            translationParams: Armor_Registration.MaleWorldModelConverter.DoNotShortCircuit());
                        return new ParseResult((int)Armor_FieldIndex.MaleWorldModel, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Armor_FieldIndex.MaleMessageIcon)
                    {
                        this.FemaleBipedModel = ModelBinaryOverlay.ModelFactory(
                            stream: stream,
                            package: _package,
                            translationParams: Armor_Registration.FemaleBipedModelConverter.DoNotShortCircuit());
                        return new ParseResult((int)Armor_FieldIndex.FemaleBipedModel, type);
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)Armor_FieldIndex.FemaleBipedModel)
                    {
                        this.FemaleWorldModel = ModelBinaryOverlay.ModelFactory(
                            stream: stream,
                            package: _package,
                            translationParams: Armor_Registration.FemaleWorldModelConverter.DoNotShortCircuit());
                        return new ParseResult((int)Armor_FieldIndex.FemaleWorldModel, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                this.MaleBipedModel = ModelBinaryOverlay.ModelFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: translationParams.DoNotShortCircuit());
                                return new ParseResult((int)Armor_FieldIndex.MaleBipedModel, type);
                            }
                            case 1:
                            {
                                this.MaleWorldModel = ModelBinaryOverlay.ModelFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: Armor_Registration.MaleWorldModelConverter.DoNotShortCircuit());
                                return new ParseResult((int)Armor_FieldIndex.MaleWorldModel, type);
                            }
                            case 2:
                            {
                                this.FemaleBipedModel = ModelBinaryOverlay.ModelFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: Armor_Registration.FemaleBipedModelConverter.DoNotShortCircuit());
                                return new ParseResult((int)Armor_FieldIndex.FemaleBipedModel, type);
                            }
                            case 3:
                            {
                                this.FemaleWorldModel = ModelBinaryOverlay.ModelFactory(
                                    stream: stream,
                                    package: _package,
                                    translationParams: Armor_Registration.FemaleWorldModelConverter.DoNotShortCircuit());
                                return new ParseResult((int)Armor_FieldIndex.FemaleWorldModel, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.MOD2:
                case RecordTypeInts.MO2T:
                case RecordTypeInts.MO2S:
                {
                    this.MaleWorldModel = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.With(Armor_Registration.MaleWorldModelConverter).DoNotShortCircuit());
                    return (int)Armor_FieldIndex.MaleWorldModel;
                }
                case RecordTypeInts.ICON:
                {
                    _MaleIconLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.MaleIcon;
                }
                case RecordTypeInts.MICO:
                {
                    _MaleMessageIconLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.MaleMessageIcon;
                }
                case RecordTypeInts.MOD3:
                case RecordTypeInts.MO3T:
                case RecordTypeInts.MO3S:
                case RecordTypeInts.MOSD:
                {
                    this.FemaleBipedModel = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.With(Armor_Registration.FemaleBipedModelConverter).DoNotShortCircuit());
                    return (int)Armor_FieldIndex.FemaleBipedModel;
                }
                case RecordTypeInts.MOD4:
                case RecordTypeInts.MO4T:
                case RecordTypeInts.MO4S:
                {
                    this.FemaleWorldModel = ModelBinaryOverlay.ModelFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.With(Armor_Registration.FemaleWorldModelConverter).DoNotShortCircuit());
                    return (int)Armor_FieldIndex.FemaleWorldModel;
                }
                case RecordTypeInts.ICO2:
                {
                    _FemaleIconLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.FemaleIcon;
                }
                case RecordTypeInts.MIC2:
                {
                    _FemaleMessageIconLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.FemaleMessageIcon;
                }
                case RecordTypeInts.BMCT:
                {
                    _RagdollConstraintTemplateLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.RagdollConstraintTemplate;
                }
                case RecordTypeInts.DEST:
                case RecordTypeInts.DSTD:
                {
                    this.Destructible = DestructibleBinaryOverlay.DestructibleFactory(
                        stream: stream,
                        package: _package,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Armor_FieldIndex.Destructible;
                }
                case RecordTypeInts.REPL:
                {
                    _RepairListLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.RepairList;
                }
                case RecordTypeInts.BIPL:
                {
                    _BipedModelListLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.BipedModelList;
                }
                case RecordTypeInts.ETYP:
                {
                    _EquipmentTypeLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.EquipmentType;
                }
                case RecordTypeInts.YNAM:
                {
                    _PickUpSoundLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.PickUpSound;
                }
                case RecordTypeInts.ZNAM:
                {
                    _DropSoundLocation = (stream.Position - offset);
                    return (int)Armor_FieldIndex.DropSound;
                }
                case RecordTypeInts.DATA:
                {
                    _DATALocation = new((stream.Position - offset) + _package.MetaData.Constants.SubConstants.TypeAndLengthLength, finalPos - offset - 1);
                    return (int)Armor_FieldIndex.Weight;
                }
                case RecordTypeInts.DNAM:
                {
                    _DNAMLocation = new((stream.Position - offset) + _package.MetaData.Constants.SubConstants.TypeAndLengthLength, finalPos - offset - 1);
                    return (int)Armor_FieldIndex.ModulatesVoice;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
